EbmlElement* findNextEbmlElement(IOCallback &DataStream, const EbmlSemanticContext &Context, int &UpperLevel, uint64 MaxDataSize, bool AllowDummyElt, unsigned int MaxLowerLevel) {
    // Placeholder for the current position in the data stream
    uint64 position = DataStream.getPosition();
    uint64 remainingSize = MaxDataSize;

    // Read the potential EBML element ID
    uint8 id = 0;
    if (!DataStream.read(&id, sizeof(id)))
        return nullptr;

    if (id == 0) {
        // Dummy element handling
        if (AllowDummyElt) {
            // Skip dummy element
            // Dummy element has no size, just skip the ID
            return nullptr;
        }
        return nullptr;
    }

    // Read the size of the element based on the ID
    size_t sizeSize = getEbmlSizeSize(id);
    if (sizeSize == 0)
        return nullptr;

    uint64 size = 0;
    if (!readEbmlSize(DataStream, id, size))
        return nullptr;

    // Validate that the element's data fits within the available data
    if (size > remainingSize)
        return nullptr;

    // Check the level of the element
    int lowerLevel = getEbmlLevel(id);
    if (lowerLevel > static_cast<int>(MaxLowerLevel))
        return nullptr;

    // Create the EBML element
    EbmlElement* element = new EbmlElement();
    if (!element)
        return nullptr;

    element->id = id;
    element->size = size;
    element->level = lowerLevel;
    element->context = Context;

    // Update the upper level if necessary
    if (lowerLevel > UpperLevel) {
        UpperLevel = lowerLevel;
    }

    return element;
}

EbmlElement* findNextEbmlElement(IOCallback &DataStream, const EbmlSemanticContext &Context, int &UpperLevel, uint64 MaxDataSize, bool AllowDummyElt, unsigned int MaxLowerLevel) {
    uint64 bytesRead = 0;
    uint8 id = 0;
    uint64 size = 0;
    int level = 0;

    // Read potential ID and size from the data stream
    if (!DataStream.read(&id, sizeof(id), bytesRead) || bytesRead < sizeof(id)) {
        return nullptr;
    }

    if (!DataStream.readSize(size, bytesRead) || bytesRead < sizeof(id) + sizeof(size)) {
        return nullptr;
    }

    if (bytesRead + size > MaxDataSize) {
        return nullptr;
    }

    if (size == 0 && !AllowDummyElt) {
        return nullptr;
    }

    // Determine level based on the ID
    level = Context.getLevelFromId(id);
    if (level < 0) {
        return nullptr;
    }

    if (level > MaxLowerLevel) {
        return nullptr;
    }

    // Create and return the EBML element
    return new EbmlElement(id, size, Context);
}

EbmlElement* findNextEbmlElement(IOCallback &DataStream, const EbmlSemanticContext &Context, int &UpperLevel, uint64 MaxDataSize, bool AllowDummyElt, unsigned int MaxLowerLevel) {
    uint64 pos = DataStream.tellg();
    if (pos == DataStream.eof()) {
        return nullptr;
    }

    uint64 dataSize = 0;
    uint8 id;
    uint64 size = 0;

    if (!DataStream.read(reinterpret_cast<char*>(&id), sizeof(id))) {
        return nullptr;
    }

    if (!EbmlElement::decodeSize(DataStream, size)) {
        return nullptr;
    }

    if (DataStream.tellg() + size > MaxDataSize) {
        return nullptr;
    }

    EbmlElement* element = Context.createElement(id, size);
    if (!element) {
        return nullptr;
    }

    if (element->getLevel() > MaxLowerLevel) {
        delete element;
        return nullptr;
    }

    if (AllowDummyElt && element->isDummy()) {
        UpperLevel = element->getLevel();
        return element;
    }

    if (DataStream.read(reinterpret_cast<char*>(element->getData()), size)) {
        UpperLevel = element->getLevel();
        return element;
    }

    delete element;
    return nullptr;
}

EbmlElement* findNextEbmlElement(IOCallback &DataStream, const EbmlSemanticContext &Context, int &UpperLevel, uint64 MaxDataSize, bool AllowDummyElt, unsigned int MaxLowerLevel) {
    uint64 bytesRead = 0;
    uint64 dataSize = 0;
    unsigned char elementId;

    // Read the element ID
    if (DataStream.read(&elementId, sizeof(elementId), bytesRead) != sizeof(elementId)) {
        return nullptr;
    }

    // Determine the size of the element
    dataSize = readElementSize(DataStream, bytesRead);

    // Check if the size exceeds the maximum allowed data size
    if (dataSize > MaxDataSize) {
        return nullptr;
    }

    // Create the EBML element based on the ID and context
    EbmlElement* element = Context.createElement(elementId);

    if (!element) {
        // If dummy elements are allowed, create a dummy element
        if (AllowDummyElt) {
            element = new EbmlDummyElement(elementId, dataSize);
        } else {
            return nullptr;
        }
    }

    // Set the size of the element
    element->setSize(dataSize);

    // Validate the lower level of the element
    if (element->getLevel() > MaxLowerLevel) {
        delete element;
        return nullptr;
    }

    // Update the upper level if necessary
    if (element->getLevel() > UpperLevel) {
        UpperLevel = element->getLevel();
    }

    return element;
}

EbmlElement* FindNextEbmlElement(IOCallback &DataStream, const EbmlSemanticContext &Context, int &UpperLevel, uint64 MaxDataSize, bool AllowDummyElt, unsigned int MaxLowerLevel) {
    uint64 pos = DataStream.Tell();
    if (pos >= MaxDataSize) {
        return nullptr;
    }

    EbmlId id;
    if (!DataStream.ReadId(id)) {
        return nullptr;
    }

    EbmlElement *element = Context.Create(id);
    if (!element) {
        if (!AllowDummyElt) {
            return nullptr;
        }
        element = new EbmlDummyElement(id);
    }

    if (!element->ReadSize(DataStream)) {
        delete element;
        return nullptr;
    }

    uint64 elementSize = element->GetSize();
    if (pos + elementSize > MaxDataSize) {
        delete element;
        return nullptr;
    }

    if (element->GetLevel() > MaxLowerLevel) {
        delete element;
        return nullptr;
    }

    UpperLevel = element->GetLevel();
    return element;
}
